const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save = () => { try { localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); } catch {} };
let toastTimer;
function toast(message){ const el=$('#toast'); el.textContent=message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('show'),2400); }
const pages={contests:'竞赛大厅',overview:'我的参赛计划',notice:'通知解读',tasks:'我的备赛待办',materials:'材料预检',assistant:'规则问答'};
function go(page){ if(!pages[page]) return; $$('.page').forEach(el=>el.classList.toggle('active',el.id==='page-'+page)); $$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.page===page)); $('#breadcrumb-current').textContent=pages[page]; window.scrollTo({top:0,behavior:'smooth'}); if(page==='contests') renderContests(); if(page==='tasks') renderTasks(); if(page==='materials') renderMaterial(); }
