function renderRules(){ $('#rules-list').innerHTML=rules.map((r,i)=>`<article class="rule"><button type="button" aria-expanded="false"><span class="rule-index">${String(i+1).padStart(2,'0')}</span><span class="rule-copy"><strong>${escapeHtml(r.title)}</strong><small>${escapeHtml(r.summary)}</small></span><span class="rule-chevron">⌄</span></button><div class="rule-evidence"><span>通知摘录　</span>${escapeHtml(r.source)}</div></article>`).join(''); }
