function renderOverview(){
  const done=state.tasks.filter(t=>t.done).length;
  const allChecks=Object.values(state.checks).flat();
  $('#rule-stat').textContent=state.confirmed?'已确认':'待确认';
  $('#rule-stat-sub').textContent=state.confirmed?'可以继续准备材料':'先核对目标赛事官网';
  $('#task-stat').textContent=`${done} / ${state.tasks.length}`;
  $('#material-stat').textContent=`${allChecks.filter(Boolean).length} / ${allChecks.length}`;
  const upcoming=state.tasks.filter(t=>!t.done).slice(0,3);
  $('#overview-tasks').innerHTML=upcoming.length?upcoming.map(t=>`<div class="compact-task"><span class="mini-check"></span><p>${escapeHtml(t.title)}</p><small>${escapeHtml(t.stage)}</small></div>`).join(''):'<div class="empty-state">暂无待办，可从关注赛事创建个人备赛任务。</div>';
}
function renderTasks(){
  const done=state.tasks.filter(t=>t.done).length; const total=state.tasks.length; const percent=total?Math.round(done/total*100):0;
  $('#task-progress-label').textContent=percent+'%';$('#task-progress-count').textContent=`${done} / ${total} 项已完成`;$('#task-progress-bar').style.width=percent+'%';
  const items=state.tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done));
  $('#tasks-list').innerHTML=items.length?items.map(t=>`<div class="task-row ${t.done?'is-done':''}"><input class="task-check" type="checkbox" data-id="${escapeHtml(t.id)}" aria-label="完成 ${escapeHtml(t.title)}" ${t.done?'checked':''}><div class="task-info"><strong>${escapeHtml(t.title)}</strong><small>负责人 · ${escapeHtml(t.owner||'待分配')}</small></div><span class="task-stage">${escapeHtml(t.stage)}</span><button class="delete-task" data-delete="${escapeHtml(t.id)}" aria-label="删除 ${escapeHtml(t.title)}">×</button></div>`).join(''):'<div class="empty-state">这个筛选条件下暂无任务。</div>';
  renderOverview();
}
$('#tasks-list').addEventListener('change',e=>{if(!e.target.matches('.task-check'))return;const task=state.tasks.find(t=>t.id===e.target.dataset.id);if(task){task.done=e.target.checked;save();renderTasks();}});
$('#tasks-list').addEventListener('click',e=>{const b=e.target.closest('[data-delete]');if(!b)return;state.tasks=state.tasks.filter(t=>t.id!==b.dataset.delete);save();renderTasks();toast('任务已删除');});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{taskFilter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderTasks();}));
