const materials={
  doc:{eyebrow:'PROJECT DOCUMENT',title:'项目文档',description:'按赛事要求整理作品说明、方案、分工和必要证明材料。',hint:'文档文件 · .doc / .docx / .pdf',accept:'.doc,.docx,.pdf',tip:'具体模板、格式、页数和命名规则请以目标赛事通知为准。',source:'通用提示：记录作品内容、团队分工及赛事要求的必要信息；如赛事要求披露所用工具，按规定如实说明。',checks:[['资格与报名信息','核对团队成员、专业、学号和报名字段。'],['作品说明与方案','按赛事规定说明背景、方法、成果与应用。'],['团队分工与指导信息','核对队员、负责人及指导教师信息。'],['模板、格式与文件命名','使用主办方提供的最新模板和命名方式。'],['提交凭证与版本留档','保存最终文件、提交回执和通知版本。']]},
  ppt:{eyebrow:'PROJECT PRESENTATION',title:'项目方案与展示材料',description:'按赛事通知准备方案、展示或答辩文件。',hint:'演示文稿 · .ppt / .pptx',accept:'.ppt,.pptx',tip:'请核对页数、模板、演讲时长和文件大小限制。',source:'通用提示：演示内容和格式以该赛事当年规则为准。',checks:[['问题和目标','说明作品要解决的问题及参赛目标。'],['方案和实现','展示关键方案、设计过程或技术路线。'],['成果与证据','准备作品展示、数据或测试结果。'],['分工和答辩安排','确认讲解顺序、负责人和备用材料。']]},
  video:{eyebrow:'DEMONSTRATION MATERIAL',title:'演示材料',description:'仅在赛事要求时准备视频、演示程序或现场展示材料。',hint:'视频或演示文件',accept:'.mp4,video/*,.zip',tip:'时长、格式、文件大小及播放环境按赛事通知核对。',source:'通用提示：不同赛事的演示要求不同，请逐项对照当届通知。',checks:[['材料形式','确认需要录屏、视频、实物或现场演示。'],['技术规格','检查格式、时长、大小和运行环境。'],['内容完整性','覆盖赛事要求的功能、过程或结果。'],['备份与播放','准备备用文件并提前检查播放效果。']]}
};
function renderMaterial(){const m=materials[materialType];const checks=state.checks[materialType];$('#material-eyebrow').textContent=m.eyebrow;$('#material-heading').textContent=m.title;$('#material-description').textContent=m.description;$('#material-count').textContent=`${checks.filter(Boolean).length} / ${checks.length} 项已确认`;$('#material-source').textContent=m.source;$('#upload-hint').textContent=m.hint;$('#material-tip').textContent=m.tip;$('#material-file').accept=m.accept;$('#material-file').value='';const file=files[materialType];$('#selected-file').textContent=file||'尚未选择文件';$('#material-checks').innerHTML=m.checks.map((c,i)=>`<div class="material-check"><input type="checkbox" class="check-input" id="check-${i}" data-check="${i}" ${checks[i]?'checked':''}><label for="check-${i}"><strong>${escapeHtml(c[0])}</strong><small>${escapeHtml(c[1])}</small></label></div>`).join('');$$('.material-tab').forEach(b=>{const active=b.dataset.material===materialType;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});renderOverview();}
$$('.material-tab').forEach(b=>b.addEventListener('click',()=>{materialType=b.dataset.material;renderMaterial();}));
$('#material-checks').addEventListener('change',e=>{if(!e.target.matches('[data-check]'))return;state.checks[materialType][Number(e.target.dataset.check)]=e.target.checked;save();renderMaterial();});
$('#material-file').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const mb=f.size/1000000;let note=`已选择：${f.name} · ${mb.toFixed(2)} MB`;if(materialType==='video')note+=mb>100?' · 超过 100 MB':' · 大小在 100 MB 内';files[materialType]=note;$('#selected-file').textContent=note;});
$('#export-checklist').addEventListener('click',()=>{let output='赛事材料管家 · 我的准备清单\n\n团队待办\n';state.tasks.forEach(t=>output+=`${t.done?'[✓]':'[ ]'} ${t.title}｜${t.owner}｜${t.stage}\n`);for(const [key,m] of Object.entries(materials)){output+=`\n${m.title}\n`;m.checks.forEach((c,i)=>output+=`${state.checks[key][i]?'[✓]':'[ ]'} ${c[0]}\n`);}output+='\n实际要求请以赛事官方通知为准。';const url=URL.createObjectURL(new Blob([output],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='赛事准备清单.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('准备清单已导出');});

function answerFor(q){
  if(/报名|截止|日期|时间|什么时候/.test(q))return ['请查看竞赛信息库中的“准确报名截止”字段；如果显示未核实，请打开赛事官网，按本届通知填写日期后设置浏览器提醒。','赛事官方通知中的报名与提交时间'];
  if(/人数|队员|组队|团队成员|资格|专业|年级/.test(q))return ['核对参赛对象、专业年级、组队人数、跨校限制和每人可报名数量；这些条件以赛事当年通知为准。','赛事官方通知中的参赛对象与组队要求'];
  if(/材料|提交|文档|作品|视频|ppt|文件/i.test(q))return ['先查看通知中的必交材料、模板、文件格式、命名、大小限制和提交渠道，再使用材料预检清单逐项确认。','赛事官方通知中的作品与提交要求'];
  if(/评分|评审|奖项|分数/.test(q))return ['不同赛事和赛道的评审办法不同。请打开官方通知中的评分标准、奖项设置和评审流程核对。','赛事官方通知中的评审与奖项说明'];
  if(/原创|版权|知识产权|数据/.test(q))return ['检查赛事规则里的原创性、引用、知识产权、数据使用和保密要求，并保留团队自己的过程记录。','赛事官方规则中的学术诚信与合规条款'];
  return ['当前没有载入特定赛事通知。请先在竞赛信息库选择赛事并打开官网；我可以帮你整理报名、组队、材料和时间节点的核对事项。','通用准备提示；具体规则以赛事官网为准'];
}
function ask(question){const q=question.trim();if(!q)return;const messages=$('#chat-messages');const user=document.createElement('div');user.className='message user-message';user.innerHTML=`<div class="bubble">${escapeHtml(q)}</div>`;messages.appendChild(user);const [answer,source]=answerFor(q);const reply=document.createElement('div');reply.className='message assistant-message';reply.innerHTML=`<span class="message-avatar">✳</span><div><div class="bubble">${escapeHtml(answer)}<div class="answer-source">依据：${escapeHtml(source)}</div></div><small>请结合通知原文核对</small></div>`;messages.appendChild(reply);messages.scrollTop=messages.scrollHeight;}
$('#chat-form').addEventListener('submit',e=>{e.preventDefault();ask($('#chat-input').value);$('#chat-input').value='';});
$$('[data-question]').forEach(b=>b.addEventListener('click',()=>ask(b.dataset.question)));
$('#clear-personal-records').addEventListener('click',clearPersonalRecords);
const { contests: contestCatalog, contestsKey: CONTESTS_KEY, legacyContestsKey: LEGACY_CONTESTS_KEY, directorySource: DIRECTORY_SOURCE } = window.ContestData;
let contestState={favorites:[],reminders:{},noticeSent:[],subscriptions:[],updateHistory:[],custom:[],progress:{},eventTasks:{},eventNotes:{},materialChecks:{},dismissedReminders:[],majorPreference:'',majorOnly:false,filters:{}};
try{
 const stored=JSON.parse(localStorage.getItem(CONTESTS_KEY)||'null');
 if(stored&&typeof stored==='object')contestState=Object.assign(contestState,stored);
 else{
  const legacy=JSON.parse(localStorage.getItem(LEGACY_CONTESTS_KEY)||'null');
  if(Array.isArray(legacy)){contestState.favorites=legacy.filter(function(c){return c.favorite;}).map(function(c){return c.id;});contestState.custom=legacy.filter(function(c){return c&&!c.demo&&String(c.name||'').toLowerCase().indexOf('aigc')<0;}).map(function(c){return {id:c.id||'custom-'+Date.now(),name:c.name||'',category:c.category||'待分类',organizer:c.organizer||'主办方待确认',season:c.season||c.deadlineNote||'时间待补充',sourceUrl:c.sourceUrl||'',favorite:!!c.favorite,custom:true};});}
 }
}catch{}
if(!contestState.reminders||typeof contestState.reminders!=='object')contestState.reminders={};
if(!contestState.progress||typeof contestState.progress!=='object')contestState.progress={};
if(!contestState.eventTasks||typeof contestState.eventTasks!=='object')contestState.eventTasks={};
if(!contestState.eventNotes||typeof contestState.eventNotes!=='object')contestState.eventNotes={};
if(!contestState.materialChecks||typeof contestState.materialChecks!=='object')contestState.materialChecks={};
if(!Array.isArray(contestState.dismissedReminders))contestState.dismissedReminders=[];
if(!Array.isArray(contestState.favorites))contestState.favorites=[];
if(!Array.isArray(contestState.noticeSent))contestState.noticeSent=[];
if(!Array.isArray(contestState.subscriptions))contestState.subscriptions=[];
if(!Array.isArray(contestState.updateHistory))contestState.updateHistory=[];
if(!Array.isArray(contestState.custom))contestState.custom=[];
if(!contestState.filters||typeof contestState.filters!=='object')contestState.filters={};
contestState.custom=contestState.custom.filter(function(c){return c&&!/aigc|生成式人工智能项目/i.test(String(c.name||''));});
const favorites=new Set(contestState.favorites);
let contests=contestCatalog.concat(contestState.custom).map(function(c){return Object.assign({},c,{favorite:favorites.has(c.id)});});
const saveContestState=function(){contestState.favorites=Array.from(favorites);try{localStorage.setItem(CONTESTS_KEY,JSON.stringify(contestState));}catch{}};
const localToday=function(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
contestCatalog.forEach(function(c){if(c.verifiedDeadline&&c.verifiedDeadline>=localToday()&&contestState.dismissedReminders.indexOf(c.id)<0&&!contestState.reminders[c.id])contestState.reminders[c.id]={deadline:c.verifiedDeadline,daysBefore:7,source:'official'};});
saveContestState();
const safeSourceUrl=function(value){try{const u=new URL(value);return (u.protocol==='https:'||u.protocol==='http:')?u.href:'';}catch{return '';}};
const CATALOG_SNAPSHOT_KEY='contest-catalog-snapshot-v1';
function catalogSnapshotFor(c){return {season:c.season||'',schedule:c.schedule2026||c.season||'',status:c.status2026||'',basis:c.statusBasis||'',source:c.sourceUrl||'',statusSource:c.statusSourceUrl||'',note:c.statusNote||'',eligibility:c.eligibility||'',organizer:c.organizer||'',deadline:c.verifiedDeadline||'',milestones:JSON.stringify(c.milestones||[])};}
function detectCatalogUpdates(){let previous=null;try{previous=JSON.parse(localStorage.getItem(CATALOG_SNAPSHOT_KEY)||'null');}catch{}const current={};contestCatalog.forEach(function(c){current[c.id]=catalogSnapshotFor(c);});if(previous&&typeof previous==='object'&&!Array.isArray(previous)){const found=[];contestCatalog.forEach(function(c){const old=previous[c.id],now=current[c.id];if(!old||JSON.stringify(old)===JSON.stringify(now))return;const changes=[];if(old.schedule!==now.schedule||old.season!==now.season)changes.push('赛程更新');if(old.status!==now.status)changes.push('状态更新');if(old.note!==now.note||old.eligibility!==now.eligibility)changes.push('官方通知说明或参赛要求更新');if(old.deadline!==now.deadline)changes.push('报名截止更新');if(old.milestones!==now.milestones)changes.push('赛事节点更新');if(old.source!==now.source||old.statusSource!==now.statusSource)changes.push('官方来源更新');if(!changes.length)changes.push('赛事信息更新');const entry={id:'update-'+Date.now()+'-'+c.id,contestId:c.id,contestName:c.name,updatedAt:new Date().toISOString(),label:changes.join('、'),oldSchedule:old.schedule||old.season||'未记录',newSchedule:now.schedule||now.season||'未记录',oldStatus:old.status||'未记录',newStatus:now.status||'未记录',sourceUrl:safeSourceUrl(c.statusSourceUrl)||safeSourceUrl(c.sourceUrl)||''};contestState.updateHistory.unshift(entry);found.push(entry);});if(contestState.updateHistory.length>600)contestState.updateHistory=contestState.updateHistory.slice(0,600);if(found.length){saveContestState();const subscribed=found.filter(function(item){return contestState.subscriptions.indexOf(item.contestId)>=0;});if(subscribed.length&&'Notification'in window&&Notification.permission==='granted'){try{new Notification('你订阅的赛事有更新',{body:subscribed.slice(0,3).map(function(item){return item.contestName+'：'+item.label;}).join('；')+(subscribed.length>3?'等 '+subscribed.length+' 项':'')+'. 打开网页查看变更记录。',tag:'contest-directory-update-'+localToday()});}catch{}}}}try{localStorage.setItem(CATALOG_SNAPSHOT_KEY,JSON.stringify(current));}catch{}}
detectCatalogUpdates();
const reminderFor=function(c){return contestState.reminders[c.id]||null;};
const deadlineFor=function(c){const r=reminderFor(c);return r&&r.deadline?r.deadline:(c.verifiedDeadline||'');};
const contestDaysLeft=function(c){const value=deadlineFor(c);if(!value)return null;const d=new Date(value+'T00:00:00');if(Number.isNaN(d.getTime()))return null;const t=new Date();t.setHours(0,0,0,0);return Math.round((d.getTime()-t.getTime())/86400000);};
const displayDate=function(value){if(!value)return '未登记';const d=new Date(value+'T00:00:00');return Number.isNaN(d.getTime())?value:new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric'}).format(d);};
const registrationMonths=function(c){const part=String(c.season||'').split('报名')[0];const nums=(part.match(/\d+/g)||[]).map(Number).filter(function(n){return n>=1&&n<=12;});if(nums.length===0&&c.verifiedDeadline){const m=Number(c.verifiedDeadline.slice(5,7));return m>=1&&m<=12?[m]:[];}if(nums.length===0)return [];if(nums.length===1)return [nums[0]];const start=Math.min(nums[0],nums[1]),end=Math.max(nums[0],nums[1]),months=[];for(let m=start;m<=end;m++)months.push(m);return months;};
