function contestMilestones(c){const list=Array.isArray(c.milestones)?c.milestones.slice():[],deadline=deadlineFor(c);if(deadline&&!list.some(function(m){return m.date===deadline&&m.kind==='deadline';}))list.push({id:'registration-deadline',date:deadline,label:c.deadlineLabel||'报名截止',kind:'deadline',precision:'day'});return list.map(function(m,index){return Object.assign({id:'milestone-'+index,contestId:c.id,contestName:c.name,category:c.category,region:c.region||'全国',school:c.school||'',sourceUrl:c.sourceUrl||''},m);});}
